@import 'c/rlySharedStyles';

:host {
    padding-bottom: 1.5rem;
    display: block;
    --rr-blue: #0176d3;
    --rr-blue-2: #eef4ff;
    --rr-link: #0b5cab;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
    --rr-soft: #f0f0f0;
    --rr-head-bg: #fafaf9;
    --rr-ok: #2e844a;
    --rr-ok-2: #ebf7e6;
    --rr-bad: #ba0517;
    --rr-bad-2: #feded8;
    --rr-warn: #8c4b02;
    --rr-warn-2: #fef1cd;
    --rr-violet: #5a1ba9;
    --rr-violet-2: #f2eafe;
    --rr-mono: ui-monospace, Menlo, Consolas, monospace;
}

/* the page fills the tab's height: each section scrolls inside it, the page itself doesn't */
.rr-page { display: flex; gap: 12px; height: calc(100vh - 190px); min-height: 480px; color: var(--rr-ink); position: relative; }
.rr-page p { margin: 0; }
.rr-main { position: relative; flex: 1 1 auto; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; }
.rr-card { background: #fff; border: 1px solid var(--rr-line); border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); min-width: 0; }
.rr-grow { flex: 1 1 auto; }
.rr-mono { font-family: var(--rr-mono); font-size: 12px; white-space: nowrap; }
.rr-break { white-space: normal; word-break: break-all; }
.rr-msg { padding: 8px 10px; border-radius: 4px; font-size: 12px; flex: none; }
.rr-link { border: 0; background: none; padding: 0; font: inherit; color: var(--rr-link); cursor: pointer; white-space: nowrap; text-align: left; }
.rr-link.rr-wrap { white-space: normal; }
.rr-link:hover, .rr-a:hover { text-decoration: underline; }
.rr-link:disabled { color: var(--rr-muted); cursor: default; }
.rr-a { color: var(--rr-link); text-decoration: none; white-space: nowrap; }
.rr-link:focus-visible, .rr-a:focus-visible, .rr-chip:focus-visible, .rr-brl:focus-visible, .rr-pill:focus-visible, .rr-tile-bad:focus-visible, .rr-rowbtn:focus-visible {
    outline: 2px solid var(--rr-blue); outline-offset: 2px;
}

/* header */
.rr-head { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; padding: 10px 14px; position: relative; }
.rr-head-icon { width: 32px; height: 32px; border-radius: 4px; background: #06a59a; flex: none; display: inline-flex; align-items: center; justify-content: center; }
.rr-head-text { flex: 1 1 160px; min-width: 0; }
.rr-title { margin: 0; font-size: 17px; font-weight: 700; line-height: 1.2; }
.rr-repo { min-width: 220px; max-width: 320px; }
.rr-cd { position: relative; display: inline-flex; align-items: center; font-size: 12px; color: var(--rr-muted); white-space: nowrap; }
.rr-live { display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: var(--rr-ok); margin-right: 6px; box-shadow: 0 0 0 3px #cdeccb; }
.rr-live-off { background: #939393; box-shadow: 0 0 0 3px #e5e5e5; }
.rr-live-bad { background: var(--rr-bad); box-shadow: 0 0 0 3px var(--rr-bad-2); }
/* the countdown: one-second steps (each iteration counts down, the end reads the board again) */
.rr-tick { position: absolute; left: 0; bottom: 0; width: 1px; height: 1px; opacity: 0.01; pointer-events: none; animation: rr-tick 1s linear; }
.rr-tick-fast { animation-iteration-count: 10; }
.rr-tick-slow { animation-iteration-count: 30; }
@keyframes rr-tick { from { transform: translateX(0); } to { transform: translateX(1px); } }
.rr-meter { position: absolute; left: 0; right: 0; bottom: 0; height: 2px; overflow: hidden; border-radius: 0 0 4px 4px; }
.rr-meter-fill { display: block; height: 100%; width: 100%; background: var(--rr-blue); opacity: 0.35; transform-origin: left center; animation: rr-countdown 30s linear forwards; }
.rr-meter-fast { animation-duration: 10s; }
@keyframes rr-countdown { from { transform: scaleX(0); } to { transform: scaleX(1); } }

/* tiles */
.rr-tiles { flex: none; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.rr-tile { display: flex; align-items: baseline; gap: 10px; padding: 9px 14px; font: inherit; color: inherit; text-align: left; }
.rr-tile-n { font-size: 24px; font-weight: 700; line-height: 1.1; display: inline-flex; align-items: center; }
.rr-tile-l { font-size: 12px; color: var(--rr-muted); }
.rr-tile-run { background: var(--rr-blue-2); border-color: #b9d6f2; }
.rr-tile-run .rr-tile-n { color: var(--rr-blue); }
.rr-tile-br { background: var(--rr-violet-2); border-color: #dccbf7; }
.rr-tile-br .rr-tile-n { color: var(--rr-violet); }
.rr-tile-ok { background: var(--rr-ok-2); border-color: #c3e3be; }
.rr-tile-ok .rr-tile-n { color: var(--rr-ok); }
.rr-tile-bad { border-color: #f3b5ab; background: #fff7f6; cursor: pointer; }
.rr-tile-bad .rr-tile-n { color: var(--rr-bad); }
.rr-tile-bad:hover { box-shadow: 0 0 0 1px var(--rr-bad); }
.rr-tile-quiet { cursor: pointer; }
.rr-spin { display: inline-block; width: 13px; height: 13px; margin-left: 6px; border: 2px solid #b6d5f5; border-top-color: var(--rr-blue); border-radius: 50%; animation: rr-rot 1s linear infinite; }
@keyframes rr-rot { to { transform: rotate(360deg); } }

/* sections: a header, a body that scrolls, a footer */
.rr-row2 { flex: 1 1 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); gap: 12px; }
.rr-runs { flex: 1.15 1 0; }
.rr-sec { display: flex; flex-direction: column; min-height: 0; }
.rr-ct { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 8px 12px; border-bottom: 1px solid var(--rr-line); }
.rr-h { margin: 0; font-size: 14px; font-weight: 700; white-space: nowrap; }
.rr-c { font-size: 12px; color: var(--rr-muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.rr-search { margin-left: auto; flex: 1 1 160px; min-width: 140px; max-width: 300px; }
.rr-body { flex: 1 1 auto; min-height: 0; overflow: auto; position: relative; }
.rr-foot { flex: none; display: flex; justify-content: space-between; gap: 8px; padding: 5px 12px; border-top: 1px solid var(--rr-line); font-size: 11.5px; color: var(--rr-muted); }
.rr-empty { padding: 16px 12px; font-size: 13px; color: var(--rr-muted); }
.rr-empty-tight { padding: 10px 12px; font-size: 12px; }

/* badges and dots */
.rr-badge { display: inline-flex; align-items: center; height: 20px; padding: 0 9px; border-radius: 10px; font-size: 11px; font-weight: 700; white-space: nowrap; flex: none; }
.rr-b-run { background: var(--rr-blue-2); color: #014486; }
.rr-b-ok { background: var(--rr-ok-2); color: var(--rr-ok); }
.rr-b-bad { background: var(--rr-bad-2); color: #8e030f; }
.rr-b-q { background: #f3f3f3; color: #444; }
.rr-b-warn { background: var(--rr-warn-2); color: var(--rr-warn); }
.rr-dot { display: block; width: 9px; height: 9px; border-radius: 50%; }
.rr-d-run { background: var(--rr-blue); }
.rr-d-ok { background: var(--rr-ok); }
.rr-d-bad { background: var(--rr-bad); }
.rr-d-idle { background: #c9c9c9; }
.rr-d-warn { background: #dd7a01; }
.rr-m { font-size: 12px; color: var(--rr-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }

/* route */
.rr-group { position: sticky; top: 0; z-index: 1; padding: 4px 12px; background: var(--rr-head-bg); border-bottom: 1px solid var(--rr-line);
    font-size: 11px; letter-spacing: 0.03em; text-transform: uppercase; color: var(--rr-muted); }
.rr-lane { display: grid; grid-template-columns: 118px minmax(0, 1fr); gap: 10px; align-items: center; padding: 7px 12px; border-bottom: 1px solid var(--rr-soft); }
.rr-ln { min-width: 0; }
.rr-ln-name { display: block; font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-ln small { display: block; font-size: 11px; color: var(--rr-muted); }
.rr-chip { display: flex; align-items: center; gap: 10px; min-width: 0; padding: 4px 12px 4px 6px; border: 1px solid var(--rr-line); border-radius: 18px; background: #fff; cursor: pointer; }
.rr-chip:hover { border-color: var(--rr-blue); }
.rr-chip-sel { border-color: var(--rr-blue); box-shadow: 0 0 0 1px var(--rr-blue); }
.rr-chip-idle { cursor: default; }
.rr-chip-run { background: #f6faff; border-color: #b9d6f2; }
.rr-chip-ok { background: #f6fbf4; border-color: #c3e3be; }
.rr-chip-bad { background: #fff7f6; border-color: #f3b5ab; }
.rr-segs { display: flex; gap: 3px; margin-left: auto; flex: none; }
.rr-seg { display: block; width: 14px; height: 6px; border-radius: 3px; background: #e5e5e5; }
.rr-seg-done { background: var(--rr-ok); }
.rr-seg-run { background: var(--rr-blue); }
.rr-seg-bad { background: var(--rr-bad); }

/* active branches */
.rr-brl { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 7px 12px; border-bottom: 1px solid var(--rr-soft); cursor: pointer; }
.rr-brl:hover, .rr-brl-sel { background: #f4f8fe; }
.rr-brl-text { min-width: 0; }
.rr-brl .rr-m { font-size: 11px; }

/* runs */
.rr-pills { display: flex; flex-wrap: wrap; gap: 6px; }
.rr-pill { height: 24px; padding: 0 10px; border: 1px solid #c9c9c9; border-radius: 12px; background: #fff; color: var(--rr-ink); font: inherit; font-size: 12px; white-space: nowrap; cursor: pointer; }
.rr-pill:hover { border-color: var(--rr-blue); }
.rr-pill-on { background: var(--rr-blue); border-color: var(--rr-blue); color: #fff; }
.rr-table { width: 100%; border-collapse: separate; border-spacing: 0; }
.rr-table th { position: sticky; top: 0; z-index: 1; padding: 7px 10px; background: var(--rr-head-bg); border-bottom: 1px solid var(--rr-line);
    font-size: 11px; font-weight: 400; letter-spacing: 0.03em; text-transform: uppercase; color: var(--rr-muted); text-align: left; white-space: nowrap; }
.rr-table td { padding: 6px 10px; border-bottom: 1px solid var(--rr-soft); font-size: 12.5px; white-space: nowrap; }
.rr-tr { cursor: pointer; }
.rr-tr:hover td { background: #fafcff; }
.rr-tr-sel td, .rr-tr-sel:hover td { background: #f4f8fe; }
.rr-rowbtn { border: 0; background: none; padding: 0; font: inherit; color: inherit; cursor: pointer; text-align: left; }

/* run details */
.rr-side { width: 340px; flex: none; display: flex; flex-direction: column; min-height: 0; }
.rr-kv { display: grid; grid-template-columns: 92px minmax(0, 1fr); gap: 3px 10px; margin: 0; padding: 10px 12px; border-bottom: 1px solid var(--rr-line); font-size: 12.5px; }
.rr-kv dt { color: var(--rr-muted); }
.rr-kv dd { margin: 0; min-width: 0; }
.rr-kv-status { font-weight: 700; }
.rr-tone-run { color: var(--rr-blue); }
.rr-tone-ok { color: var(--rr-ok); }
.rr-tone-bad { color: var(--rr-bad); }
.rr-tone-none { color: var(--rr-muted); }
.rr-steps { margin: 0; padding: 0; list-style: none; }
.rr-st { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 7px 12px; border-bottom: 1px solid #f4f4f4; font-size: 12.5px; }
.rr-ic { width: 16px; height: 16px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; color: #fff; }
.rr-ic-ok { background: var(--rr-ok); }
.rr-ic-bad { background: var(--rr-bad); }
.rr-ic-skip { background: #c9c9c9; }
.rr-err { margin: 10px 12px; padding: 8px 10px; border-radius: 4px; background: var(--rr-bad-2); color: #8c0000; font-family: var(--rr-mono); font-size: 11.5px;
    white-space: pre-wrap; word-break: break-word; max-height: 220px; overflow: auto; }
.rr-links { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 8px 12px 14px; font-size: 13px; }

/* smaller screens: the details panel lies over the sections instead of taking their space */
@media (max-width: 1180px) {
    .rr-side { position: absolute; top: 0; right: 0; bottom: 0; z-index: 5; box-shadow: -4px 0 16px rgba(0, 0, 0, 0.18); }
}

/* phones and narrow windows: sections stack and the page scrolls; each section keeps its own scroll */
@media (max-width: 820px) {
    .rr-page { height: auto; min-height: 0; }
    .rr-row2 { grid-template-columns: minmax(0, 1fr); flex: none; }
    .rr-row2 .rr-sec, .rr-runs { height: 360px; flex: none; }
    .rr-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .rr-repo { min-width: 0; flex: 1 1 100%; max-width: none; }
    .rr-side { position: fixed; top: auto; left: 0; right: 0; bottom: 0; width: auto; height: 70vh; border-radius: 8px 8px 0 0; }
    .rr-search { max-width: none; flex-basis: 100%; margin-left: 0; }
}
